-- Restaurant OS — initial schema
-- Written in the PostgreSQL / SQLite common subset (see src/platform/db/migrate.ts).
--
-- Conventions
--   * Primary keys are prefixed, time-sortable text ids generated by the application.
--   * Every tenant table carries org_id and every foreign key between tenant tables is
--     COMPOSITE (org_id, x_id) so the database itself refuses cross-tenant references.
--   * Money is BIGINT minor units, rates are integer basis points, stock quantities are
--     integer thousandths of the item's base unit. No floats are stored anywhere.
--   * Timestamps are TIMESTAMPTZ (ISO-8601 text on SQLite). Calendar dates are 'YYYY-MM-DD' text.
--   * Booleans are named is_* / has_*.

-- ===========================================================================
-- Platform (not tenant-scoped)
-- ===========================================================================
CREATE TABLE plans (
  code             TEXT PRIMARY KEY,
  name             TEXT NOT NULL,
  description      TEXT NOT NULL DEFAULT '',
  price_minor      BIGINT NOT NULL DEFAULT 0,
  currency         TEXT NOT NULL DEFAULT 'KES',
  billing_interval TEXT NOT NULL DEFAULT 'month' CHECK (billing_interval IN ('month', 'year')),
  trial_days       INTEGER NOT NULL DEFAULT 14,
  limits_json      TEXT NOT NULL DEFAULT '{}',
  features_json    TEXT NOT NULL DEFAULT '[]',
  highlights_json  TEXT NOT NULL DEFAULT '[]',
  is_public        BOOLEAN NOT NULL DEFAULT TRUE,
  is_active        BOOLEAN NOT NULL DEFAULT TRUE,
  sort_order       INTEGER NOT NULL DEFAULT 0,
  created_at       TIMESTAMPTZ NOT NULL,
  updated_at       TIMESTAMPTZ NOT NULL
);

CREATE TABLE platform_admins (
  id            TEXT PRIMARY KEY,
  email         TEXT NOT NULL,
  name          TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  is_active     BOOLEAN NOT NULL DEFAULT TRUE,
  last_login_at TIMESTAMPTZ,
  created_at    TIMESTAMPTZ NOT NULL
);
CREATE UNIQUE INDEX platform_admins_email_uq ON platform_admins (lower(email));

CREATE TABLE platform_sessions (
  id           TEXT PRIMARY KEY,
  admin_id     TEXT NOT NULL REFERENCES platform_admins (id) ON DELETE CASCADE,
  token_hash   TEXT NOT NULL UNIQUE,
  ip           TEXT,
  user_agent   TEXT,
  expires_at   TIMESTAMPTZ NOT NULL,
  last_seen_at TIMESTAMPTZ NOT NULL,
  revoked_at   TIMESTAMPTZ,
  created_at   TIMESTAMPTZ NOT NULL
);

CREATE TABLE platform_audit_logs (
  id          TEXT PRIMARY KEY,
  admin_id    TEXT,
  admin_name  TEXT,
  org_id      TEXT,
  action      TEXT NOT NULL,
  summary     TEXT NOT NULL DEFAULT '',
  data_json   TEXT,
  created_at  TIMESTAMPTZ NOT NULL
);
CREATE INDEX platform_audit_created_idx ON platform_audit_logs (created_at);

CREATE TABLE rate_limits (
  key          TEXT PRIMARY KEY,
  window_start TIMESTAMPTZ NOT NULL,
  hits         INTEGER NOT NULL
);

CREATE TABLE counters (
  org_id    TEXT NOT NULL,
  branch_id TEXT NOT NULL DEFAULT '',
  scope     TEXT NOT NULL,
  value     BIGINT NOT NULL,
  PRIMARY KEY (org_id, branch_id, scope)
);

-- ===========================================================================
-- Tenancy
-- ===========================================================================
CREATE TABLE organizations (
  id                TEXT PRIMARY KEY,
  slug              TEXT NOT NULL UNIQUE,
  name              TEXT NOT NULL,
  legal_name        TEXT,
  tax_number        TEXT,
  email             TEXT,
  phone             TEXT,
  country           TEXT NOT NULL DEFAULT 'KE',
  currency          TEXT NOT NULL DEFAULT 'KES',
  timezone          TEXT NOT NULL DEFAULT 'Africa/Nairobi',
  locale            TEXT NOT NULL DEFAULT 'en-KE',
  logo_url          TEXT,
  status            TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'closed')),
  suspended_reason  TEXT,
  onboarding_status TEXT NOT NULL DEFAULT 'in_progress' CHECK (onboarding_status IN ('in_progress', 'completed')),
  onboarding_step   TEXT NOT NULL DEFAULT 'business',
  created_at        TIMESTAMPTZ NOT NULL,
  updated_at        TIMESTAMPTZ NOT NULL
);

CREATE TABLE org_settings (
  org_id                   TEXT PRIMARY KEY REFERENCES organizations (id) ON DELETE CASCADE,
  tax_label                TEXT NOT NULL DEFAULT 'VAT',
  tax_rate_bp              INTEGER NOT NULL DEFAULT 1600 CHECK (tax_rate_bp BETWEEN 0 AND 10000),
  tax_inclusive            BOOLEAN NOT NULL DEFAULT TRUE,
  service_charge_bp        INTEGER NOT NULL DEFAULT 0 CHECK (service_charge_bp BETWEEN 0 AND 10000),
  service_charge_taxable   BOOLEAN NOT NULL DEFAULT FALSE,
  service_charge_types_json TEXT NOT NULL DEFAULT '["dine_in"]',
  order_types_json         TEXT NOT NULL DEFAULT '["dine_in","takeaway","delivery"]',
  payment_methods_json     TEXT NOT NULL DEFAULT '["cash","mpesa","card"]',
  require_shift_for_cash   BOOLEAN NOT NULL DEFAULT TRUE,
  allow_negative_stock     BOOLEAN NOT NULL DEFAULT TRUE,
  kitchen_late_minutes     INTEGER NOT NULL DEFAULT 15,
  receipt_header           TEXT NOT NULL DEFAULT '',
  receipt_footer           TEXT NOT NULL DEFAULT 'Thank you for dining with us!',
  loyalty_enabled          BOOLEAN NOT NULL DEFAULT FALSE,
  loyalty_earn_points_per_100 INTEGER NOT NULL DEFAULT 1,
  loyalty_point_value_minor INTEGER NOT NULL DEFAULT 100,
  updated_at               TIMESTAMPTZ NOT NULL
);

CREATE TABLE subscriptions (
  org_id               TEXT PRIMARY KEY REFERENCES organizations (id) ON DELETE CASCADE,
  plan_code            TEXT NOT NULL REFERENCES plans (code),
  status               TEXT NOT NULL CHECK (status IN ('trialing', 'active', 'past_due', 'suspended', 'cancelled')),
  trial_ends_at        TIMESTAMPTZ,
  current_period_start TIMESTAMPTZ,
  current_period_end   TIMESTAMPTZ,
  cancel_at_period_end BOOLEAN NOT NULL DEFAULT FALSE,
  created_at           TIMESTAMPTZ NOT NULL,
  updated_at           TIMESTAMPTZ NOT NULL
);

CREATE TABLE plan_change_requests (
  id           TEXT PRIMARY KEY,
  org_id       TEXT NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
  from_plan    TEXT NOT NULL,
  to_plan      TEXT NOT NULL REFERENCES plans (code),
  status       TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),
  note         TEXT,
  requested_by TEXT,
  reviewed_by  TEXT,
  review_note  TEXT,
  created_at   TIMESTAMPTZ NOT NULL,
  reviewed_at  TIMESTAMPTZ
);
CREATE INDEX plan_change_requests_status_idx ON plan_change_requests (status, created_at);

CREATE TABLE billing_payments (
  id           TEXT PRIMARY KEY,
  org_id       TEXT NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
  amount_minor BIGINT NOT NULL CHECK (amount_minor > 0),
  currency     TEXT NOT NULL,
  method       TEXT NOT NULL,
  reference    TEXT,
  plan_code    TEXT,
  period_start TIMESTAMPTZ,
  period_end   TIMESTAMPTZ,
  recorded_by  TEXT,
  created_at   TIMESTAMPTZ NOT NULL
);
CREATE INDEX billing_payments_org_idx ON billing_payments (org_id, created_at);

CREATE TABLE branches (
  id          TEXT PRIMARY KEY,
  org_id      TEXT NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
  code        TEXT NOT NULL,
  name        TEXT NOT NULL,
  address     TEXT,
  city        TEXT,
  phone       TEXT,
  timezone    TEXT,
  display_key TEXT NOT NULL UNIQUE,
  is_active   BOOLEAN NOT NULL DEFAULT TRUE,
  created_at  TIMESTAMPTZ NOT NULL,
  updated_at  TIMESTAMPTZ NOT NULL,
  UNIQUE (org_id, id),
  UNIQUE (org_id, code)
);

-- ===========================================================================
-- Identity & access
-- ===========================================================================
CREATE TABLE roles (
  id            TEXT PRIMARY KEY,
  org_id        TEXT NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
  key           TEXT NOT NULL,
  name          TEXT NOT NULL,
  description   TEXT NOT NULL DEFAULT '',
  is_system     BOOLEAN NOT NULL DEFAULT FALSE,
  all_branches  BOOLEAN NOT NULL DEFAULT FALSE,
  created_at    TIMESTAMPTZ NOT NULL,
  updated_at    TIMESTAMPTZ NOT NULL,
  UNIQUE (org_id, id),
  UNIQUE (org_id, key)
);

CREATE TABLE role_permissions (
  role_id    TEXT NOT NULL,
  org_id     TEXT NOT NULL,
  permission TEXT NOT NULL,
  PRIMARY KEY (role_id, permission),
  FOREIGN KEY (org_id, role_id) REFERENCES roles (org_id, id) ON DELETE CASCADE
);

CREATE TABLE users (
  id                   TEXT PRIMARY KEY,
  org_id               TEXT NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
  role_id              TEXT NOT NULL,
  name                 TEXT NOT NULL,
  email                TEXT,
  phone                TEXT,
  password_hash        TEXT,
  pin_hash             TEXT,
  status               TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  color                TEXT NOT NULL DEFAULT '#4f46e5',
  must_change_password BOOLEAN NOT NULL DEFAULT FALSE,
  last_login_at        TIMESTAMPTZ,
  created_at           TIMESTAMPTZ NOT NULL,
  updated_at           TIMESTAMPTZ NOT NULL,
  UNIQUE (org_id, id),
  FOREIGN KEY (org_id, role_id) REFERENCES roles (org_id, id),
  CHECK (email IS NOT NULL OR pin_hash IS NOT NULL)
);
CREATE UNIQUE INDEX users_email_uq ON users (lower(email)) WHERE email IS NOT NULL;
CREATE INDEX users_org_idx ON users (org_id, status);

CREATE TABLE user_branches (
  org_id    TEXT NOT NULL,
  user_id   TEXT NOT NULL,
  branch_id TEXT NOT NULL,
  PRIMARY KEY (user_id, branch_id),
  FOREIGN KEY (org_id, user_id) REFERENCES users (org_id, id) ON DELETE CASCADE,
  FOREIGN KEY (org_id, branch_id) REFERENCES branches (org_id, id) ON DELETE CASCADE
);

CREATE TABLE terminals (
  id             TEXT PRIMARY KEY,
  org_id         TEXT NOT NULL,
  branch_id      TEXT NOT NULL,
  name           TEXT NOT NULL,
  kind           TEXT NOT NULL CHECK (kind IN ('pos', 'kds')),
  token_hash     TEXT UNIQUE,
  pairing_hash   TEXT,
  pairing_expires_at TIMESTAMPTZ,
  is_active      BOOLEAN NOT NULL DEFAULT TRUE,
  paired_at      TIMESTAMPTZ,
  last_seen_at   TIMESTAMPTZ,
  created_at     TIMESTAMPTZ NOT NULL,
  UNIQUE (org_id, id),
  FOREIGN KEY (org_id, branch_id) REFERENCES branches (org_id, id) ON DELETE CASCADE
);

CREATE TABLE sessions (
  id           TEXT PRIMARY KEY,
  org_id       TEXT NOT NULL,
  user_id      TEXT NOT NULL,
  branch_id    TEXT,
  terminal_id  TEXT,
  token_hash   TEXT NOT NULL UNIQUE,
  kind         TEXT NOT NULL DEFAULT 'web' CHECK (kind IN ('web', 'pin')),
  ip           TEXT,
  user_agent   TEXT,
  expires_at   TIMESTAMPTZ NOT NULL,
  last_seen_at TIMESTAMPTZ NOT NULL,
  revoked_at   TIMESTAMPTZ,
  created_at   TIMESTAMPTZ NOT NULL,
  FOREIGN KEY (org_id, user_id) REFERENCES users (org_id, id) ON DELETE CASCADE
);
CREATE INDEX sessions_user_idx ON sessions (user_id, revoked_at);

CREATE TABLE invitations (
  id          TEXT PRIMARY KEY,
  org_id      TEXT NOT NULL,
  email       TEXT NOT NULL,
  name        TEXT,
  role_id     TEXT NOT NULL,
  branch_ids_json TEXT NOT NULL DEFAULT '[]',
  token_hash  TEXT NOT NULL UNIQUE,
  expires_at  TIMESTAMPTZ NOT NULL,
  accepted_at TIMESTAMPTZ,
  invited_by  TEXT,
  created_at  TIMESTAMPTZ NOT NULL,
  FOREIGN KEY (org_id, role_id) REFERENCES roles (org_id, id) ON DELETE CASCADE
);

CREATE TABLE audit_logs (
  id          TEXT PRIMARY KEY,
  org_id      TEXT NOT NULL,
  branch_id   TEXT,
  actor_id    TEXT,
  actor_name  TEXT,
  action      TEXT NOT NULL,
  entity_type TEXT,
  entity_id   TEXT,
  summary     TEXT NOT NULL DEFAULT '',
  data_json   TEXT,
  ip          TEXT,
  created_at  TIMESTAMPTZ NOT NULL
);
CREATE INDEX audit_org_created_idx ON audit_logs (org_id, created_at);
CREATE INDEX audit_entity_idx ON audit_logs (org_id, entity_type, entity_id);

-- Transactional outbox: written in the same transaction as the change, streamed to clients over SSE.
CREATE TABLE events (
  id           {{AUTOINC_PK}},
  org_id       TEXT NOT NULL,
  branch_id    TEXT NOT NULL,
  topic        TEXT NOT NULL,
  type         TEXT NOT NULL,
  payload_json TEXT NOT NULL DEFAULT '{}',
  created_at   TIMESTAMPTZ NOT NULL
);
CREATE INDEX events_branch_idx ON events (org_id, branch_id, id);
CREATE INDEX events_created_idx ON events (created_at);

-- ===========================================================================
-- Menu
-- ===========================================================================
CREATE TABLE menu_categories (
  id         TEXT PRIMARY KEY,
  org_id     TEXT NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
  name       TEXT NOT NULL,
  color      TEXT NOT NULL DEFAULT '#64748b',
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active  BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  UNIQUE (org_id, id)
);

CREATE TABLE stations (
  id         TEXT PRIMARY KEY,
  org_id     TEXT NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
  name       TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active  BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL,
  UNIQUE (org_id, id),
  UNIQUE (org_id, name)
);

CREATE TABLE products (
  id               TEXT PRIMARY KEY,
  org_id           TEXT NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
  category_id      TEXT NOT NULL,
  station_id       TEXT,
  name             TEXT NOT NULL,
  description      TEXT NOT NULL DEFAULT '',
  sku              TEXT,
  barcode          TEXT,
  image_url        TEXT,
  base_price_minor BIGINT NOT NULL CHECK (base_price_minor >= 0),
  is_tax_exempt    BOOLEAN NOT NULL DEFAULT FALSE,
  prep_minutes     INTEGER NOT NULL DEFAULT 10,
  sort_order       INTEGER NOT NULL DEFAULT 0,
  is_active        BOOLEAN NOT NULL DEFAULT TRUE,
  created_at       TIMESTAMPTZ NOT NULL,
  updated_at       TIMESTAMPTZ NOT NULL,
  UNIQUE (org_id, id),
  FOREIGN KEY (org_id, category_id) REFERENCES menu_categories (org_id, id),
  FOREIGN KEY (org_id, station_id) REFERENCES stations (org_id, id)
);
CREATE INDEX products_cat_idx ON products (org_id, category_id, is_active);
CREATE UNIQUE INDEX products_sku_uq ON products (org_id, sku) WHERE sku IS NOT NULL;

CREATE TABLE product_variants (
  id          TEXT PRIMARY KEY,
  org_id      TEXT NOT NULL,
  product_id  TEXT NOT NULL,
  name        TEXT NOT NULL,
  price_minor BIGINT NOT NULL CHECK (price_minor >= 0),
  is_default  BOOLEAN NOT NULL DEFAULT FALSE,
  sort_order  INTEGER NOT NULL DEFAULT 0,
  UNIQUE (org_id, id),
  FOREIGN KEY (org_id, product_id) REFERENCES products (org_id, id) ON DELETE CASCADE
);

CREATE TABLE modifier_groups (
  id         TEXT PRIMARY KEY,
  org_id     TEXT NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
  name       TEXT NOT NULL,
  min_select INTEGER NOT NULL DEFAULT 0,
  max_select INTEGER NOT NULL DEFAULT 1,
  is_active  BOOLEAN NOT NULL DEFAULT TRUE,
  UNIQUE (org_id, id),
  CHECK (min_select >= 0 AND max_select >= min_select AND max_select >= 1)
);

CREATE TABLE modifier_options (
  id          TEXT PRIMARY KEY,
  org_id      TEXT NOT NULL,
  group_id    TEXT NOT NULL,
  name        TEXT NOT NULL,
  price_minor BIGINT NOT NULL DEFAULT 0 CHECK (price_minor >= 0),
  sort_order  INTEGER NOT NULL DEFAULT 0,
  is_active   BOOLEAN NOT NULL DEFAULT TRUE,
  UNIQUE (org_id, id),
  FOREIGN KEY (org_id, group_id) REFERENCES modifier_groups (org_id, id) ON DELETE CASCADE
);

CREATE TABLE product_modifier_groups (
  org_id     TEXT NOT NULL,
  product_id TEXT NOT NULL,
  group_id   TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (product_id, group_id),
  FOREIGN KEY (org_id, product_id) REFERENCES products (org_id, id) ON DELETE CASCADE,
  FOREIGN KEY (org_id, group_id) REFERENCES modifier_groups (org_id, id) ON DELETE CASCADE
);

-- Per-branch price override and availability ("86'd" items)
CREATE TABLE branch_products (
  org_id       TEXT NOT NULL,
  branch_id    TEXT NOT NULL,
  product_id   TEXT NOT NULL,
  price_minor  BIGINT,
  is_available BOOLEAN NOT NULL DEFAULT TRUE,
  updated_at   TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (branch_id, product_id),
  FOREIGN KEY (org_id, branch_id) REFERENCES branches (org_id, id) ON DELETE CASCADE,
  FOREIGN KEY (org_id, product_id) REFERENCES products (org_id, id) ON DELETE CASCADE
);

-- ===========================================================================
-- Floor
-- ===========================================================================
CREATE TABLE floor_areas (
  id         TEXT PRIMARY KEY,
  org_id     TEXT NOT NULL,
  branch_id  TEXT NOT NULL,
  name       TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  UNIQUE (org_id, id),
  FOREIGN KEY (org_id, branch_id) REFERENCES branches (org_id, id) ON DELETE CASCADE
);

CREATE TABLE dining_tables (
  id         TEXT PRIMARY KEY,
  org_id     TEXT NOT NULL,
  branch_id  TEXT NOT NULL,
  area_id    TEXT,
  label      TEXT NOT NULL,
  seats      INTEGER NOT NULL DEFAULT 4 CHECK (seats > 0),
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active  BOOLEAN NOT NULL DEFAULT TRUE,
  UNIQUE (org_id, id),
  UNIQUE (branch_id, label),
  FOREIGN KEY (org_id, branch_id) REFERENCES branches (org_id, id) ON DELETE CASCADE,
  FOREIGN KEY (org_id, area_id) REFERENCES floor_areas (org_id, id)
);

-- ===========================================================================
-- Customers & loyalty
-- ===========================================================================
CREATE TABLE customers (
  id                   TEXT PRIMARY KEY,
  org_id               TEXT NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
  name                 TEXT NOT NULL,
  phone                TEXT,
  email                TEXT,
  notes                TEXT NOT NULL DEFAULT '',
  points_balance       INTEGER NOT NULL DEFAULT 0,
  lifetime_spend_minor BIGINT NOT NULL DEFAULT 0,
  visits               INTEGER NOT NULL DEFAULT 0,
  last_visit_at        TIMESTAMPTZ,
  is_active            BOOLEAN NOT NULL DEFAULT TRUE,
  created_at           TIMESTAMPTZ NOT NULL,
  updated_at           TIMESTAMPTZ NOT NULL,
  UNIQUE (org_id, id)
);
CREATE UNIQUE INDEX customers_phone_uq ON customers (org_id, phone) WHERE phone IS NOT NULL;

CREATE TABLE loyalty_rewards (
  id          TEXT PRIMARY KEY,
  org_id      TEXT NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
  name        TEXT NOT NULL,
  points_cost INTEGER NOT NULL CHECK (points_cost > 0),
  kind        TEXT NOT NULL CHECK (kind IN ('amount_off', 'percent_off')),
  value       INTEGER NOT NULL CHECK (value > 0),
  is_active   BOOLEAN NOT NULL DEFAULT TRUE,
  created_at  TIMESTAMPTZ NOT NULL,
  UNIQUE (org_id, id)
);

CREATE TABLE loyalty_ledger (
  id            TEXT PRIMARY KEY,
  org_id        TEXT NOT NULL,
  customer_id   TEXT NOT NULL,
  order_id      TEXT,
  type          TEXT NOT NULL CHECK (type IN ('earn', 'redeem', 'adjust', 'reverse')),
  points        INTEGER NOT NULL,
  balance_after INTEGER NOT NULL,
  note          TEXT,
  created_by    TEXT,
  created_at    TIMESTAMPTZ NOT NULL,
  FOREIGN KEY (org_id, customer_id) REFERENCES customers (org_id, id) ON DELETE CASCADE
);
CREATE INDEX loyalty_ledger_customer_idx ON loyalty_ledger (org_id, customer_id, created_at);
CREATE UNIQUE INDEX loyalty_earn_once_uq ON loyalty_ledger (org_id, order_id, type) WHERE order_id IS NOT NULL AND type IN ('earn', 'redeem');

-- ===========================================================================
-- Shifts (cash drawer)
-- ===========================================================================
CREATE TABLE shifts (
  id                 TEXT PRIMARY KEY,
  org_id             TEXT NOT NULL,
  branch_id          TEXT NOT NULL,
  user_id            TEXT NOT NULL,
  terminal_id        TEXT,
  status             TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed')),
  opened_at          TIMESTAMPTZ NOT NULL,
  opening_float_minor BIGINT NOT NULL DEFAULT 0 CHECK (opening_float_minor >= 0),
  closed_at          TIMESTAMPTZ,
  closed_by          TEXT,
  expected_cash_minor BIGINT,
  counted_cash_minor BIGINT,
  variance_minor     BIGINT,
  note               TEXT,
  UNIQUE (org_id, id),
  FOREIGN KEY (org_id, branch_id) REFERENCES branches (org_id, id),
  FOREIGN KEY (org_id, user_id) REFERENCES users (org_id, id)
);
CREATE UNIQUE INDEX shifts_one_open_uq ON shifts (org_id, branch_id, user_id) WHERE status = 'open';
CREATE INDEX shifts_branch_idx ON shifts (org_id, branch_id, opened_at);

CREATE TABLE cash_movements (
  id           TEXT PRIMARY KEY,
  org_id       TEXT NOT NULL,
  shift_id     TEXT NOT NULL,
  type         TEXT NOT NULL CHECK (type IN ('pay_in', 'pay_out')),
  amount_minor BIGINT NOT NULL CHECK (amount_minor > 0),
  reason       TEXT NOT NULL,
  created_by   TEXT,
  created_at   TIMESTAMPTZ NOT NULL,
  FOREIGN KEY (org_id, shift_id) REFERENCES shifts (org_id, id) ON DELETE CASCADE
);

-- ===========================================================================
-- Orders
-- ===========================================================================
CREATE TABLE orders (
  id                    TEXT PRIMARY KEY,
  org_id                TEXT NOT NULL,
  branch_id             TEXT NOT NULL,
  seq                   INTEGER NOT NULL,
  number                TEXT NOT NULL,
  business_date         TEXT NOT NULL,
  opened_hour           INTEGER NOT NULL DEFAULT 0,
  type                  TEXT NOT NULL CHECK (type IN ('dine_in', 'takeaway', 'delivery', 'pickup')),
  status                TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed', 'void')),
  table_id              TEXT,
  customer_id           TEXT,
  guests                INTEGER,
  notes                 TEXT,
  currency              TEXT NOT NULL,
  tax_rate_bp           INTEGER NOT NULL DEFAULT 0,
  tax_inclusive         BOOLEAN NOT NULL DEFAULT TRUE,
  service_charge_bp     INTEGER NOT NULL DEFAULT 0,
  service_charge_taxable BOOLEAN NOT NULL DEFAULT FALSE,
  discount_kind         TEXT CHECK (discount_kind IN ('percent', 'amount')),
  discount_value        BIGINT,
  discount_reason       TEXT,
  discount_by           TEXT,
  reward_id             TEXT,
  reward_points         INTEGER NOT NULL DEFAULT 0,
  reward_discount_minor BIGINT NOT NULL DEFAULT 0,
  subtotal_minor        BIGINT NOT NULL DEFAULT 0,
  discount_minor        BIGINT NOT NULL DEFAULT 0,
  service_charge_minor  BIGINT NOT NULL DEFAULT 0,
  tax_minor             BIGINT NOT NULL DEFAULT 0,
  total_minor           BIGINT NOT NULL DEFAULT 0,
  paid_minor            BIGINT NOT NULL DEFAULT 0,
  tip_minor             BIGINT NOT NULL DEFAULT 0,
  opened_by             TEXT NOT NULL,
  opened_at             TIMESTAMPTZ NOT NULL,
  closed_at             TIMESTAMPTZ,
  voided_at             TIMESTAMPTZ,
  voided_by             TEXT,
  void_reason           TEXT,
  client_key            TEXT,
  version               INTEGER NOT NULL DEFAULT 1,
  updated_at            TIMESTAMPTZ NOT NULL,
  UNIQUE (org_id, id),
  FOREIGN KEY (org_id, branch_id) REFERENCES branches (org_id, id),
  FOREIGN KEY (org_id, table_id) REFERENCES dining_tables (org_id, id),
  FOREIGN KEY (org_id, customer_id) REFERENCES customers (org_id, id),
  FOREIGN KEY (org_id, opened_by) REFERENCES users (org_id, id)
);
CREATE UNIQUE INDEX orders_number_uq ON orders (org_id, branch_id, business_date, seq);
CREATE UNIQUE INDEX orders_client_key_uq ON orders (org_id, client_key) WHERE client_key IS NOT NULL;
CREATE INDEX orders_branch_status_idx ON orders (org_id, branch_id, status, opened_at);
CREATE INDEX orders_date_idx ON orders (org_id, branch_id, business_date);
CREATE INDEX orders_customer_idx ON orders (org_id, customer_id);
CREATE INDEX orders_table_idx ON orders (org_id, table_id, status);

CREATE TABLE order_items (
  id                 TEXT PRIMARY KEY,
  org_id             TEXT NOT NULL,
  order_id           TEXT NOT NULL,
  product_id         TEXT NOT NULL,
  variant_id         TEXT,
  station_id         TEXT,
  name               TEXT NOT NULL,
  variant_name       TEXT,
  qty                INTEGER NOT NULL CHECK (qty > 0),
  unit_price_minor   BIGINT NOT NULL,
  modifiers_minor    BIGINT NOT NULL DEFAULT 0,
  line_total_minor   BIGINT NOT NULL,
  is_tax_exempt      BOOLEAN NOT NULL DEFAULT FALSE,
  note               TEXT,
  status             TEXT NOT NULL DEFAULT 'held' CHECK (status IN ('held', 'sent', 'preparing', 'ready', 'served', 'void')),
  round              INTEGER NOT NULL DEFAULT 0,
  sent_at            TIMESTAMPTZ,
  started_at         TIMESTAMPTZ,
  ready_at           TIMESTAMPTZ,
  served_at          TIMESTAMPTZ,
  voided_at          TIMESTAMPTZ,
  voided_by          TEXT,
  void_reason        TEXT,
  created_at         TIMESTAMPTZ NOT NULL,
  UNIQUE (org_id, id),
  FOREIGN KEY (org_id, order_id) REFERENCES orders (org_id, id) ON DELETE CASCADE,
  FOREIGN KEY (org_id, product_id) REFERENCES products (org_id, id),
  FOREIGN KEY (org_id, station_id) REFERENCES stations (org_id, id)
);
CREATE INDEX order_items_order_idx ON order_items (org_id, order_id);
CREATE INDEX order_items_kitchen_idx ON order_items (org_id, status, sent_at);
CREATE INDEX order_items_product_idx ON order_items (org_id, product_id);

CREATE TABLE order_item_modifiers (
  id            TEXT PRIMARY KEY,
  org_id        TEXT NOT NULL,
  order_item_id TEXT NOT NULL,
  option_id     TEXT,
  group_name    TEXT NOT NULL,
  name          TEXT NOT NULL,
  price_minor   BIGINT NOT NULL DEFAULT 0,
  FOREIGN KEY (org_id, order_item_id) REFERENCES order_items (org_id, id) ON DELETE CASCADE
);
CREATE INDEX order_item_modifiers_idx ON order_item_modifiers (org_id, order_item_id);

CREATE TABLE payments (
  id                 TEXT PRIMARY KEY,
  org_id             TEXT NOT NULL,
  branch_id          TEXT NOT NULL,
  order_id           TEXT NOT NULL,
  shift_id           TEXT,
  method             TEXT NOT NULL CHECK (method IN ('cash', 'mpesa', 'card', 'bank', 'voucher', 'other')),
  amount_minor       BIGINT NOT NULL CHECK (amount_minor <> 0),
  tendered_minor     BIGINT,
  change_minor       BIGINT NOT NULL DEFAULT 0,
  tip_minor          BIGINT NOT NULL DEFAULT 0,
  reference          TEXT,
  refund_of_id       TEXT,
  reason             TEXT,
  created_by         TEXT NOT NULL,
  created_at         TIMESTAMPTZ NOT NULL,
  client_key         TEXT,
  UNIQUE (org_id, id),
  FOREIGN KEY (org_id, order_id) REFERENCES orders (org_id, id),
  FOREIGN KEY (org_id, shift_id) REFERENCES shifts (org_id, id)
);
CREATE INDEX payments_order_idx ON payments (org_id, order_id);
CREATE INDEX payments_branch_idx ON payments (org_id, branch_id, created_at);
CREATE INDEX payments_shift_idx ON payments (org_id, shift_id);
CREATE UNIQUE INDEX payments_client_key_uq ON payments (org_id, client_key) WHERE client_key IS NOT NULL;

-- ===========================================================================
-- Inventory & purchasing
-- ===========================================================================
CREATE TABLE suppliers (
  id         TEXT PRIMARY KEY,
  org_id     TEXT NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
  name       TEXT NOT NULL,
  contact    TEXT,
  phone      TEXT,
  email      TEXT,
  address    TEXT,
  notes      TEXT NOT NULL DEFAULT '',
  is_active  BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  UNIQUE (org_id, id)
);

CREATE TABLE inventory_items (
  id          TEXT PRIMARY KEY,
  org_id      TEXT NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
  name        TEXT NOT NULL,
  sku         TEXT,
  category    TEXT NOT NULL DEFAULT 'General',
  unit        TEXT NOT NULL CHECK (unit IN ('g', 'ml', 'pcs')),
  supplier_id TEXT,
  is_active   BOOLEAN NOT NULL DEFAULT TRUE,
  created_at  TIMESTAMPTZ NOT NULL,
  updated_at  TIMESTAMPTZ NOT NULL,
  UNIQUE (org_id, id),
  UNIQUE (org_id, name),
  FOREIGN KEY (org_id, supplier_id) REFERENCES suppliers (org_id, id)
);

-- Cached position per branch; the movement ledger below is the source of truth.
CREATE TABLE stock_levels (
  org_id              TEXT NOT NULL,
  branch_id           TEXT NOT NULL,
  item_id             TEXT NOT NULL,
  qty_milli           BIGINT NOT NULL DEFAULT 0,
  value_minor         BIGINT NOT NULL DEFAULT 0,
  reorder_level_milli BIGINT NOT NULL DEFAULT 0,
  par_level_milli     BIGINT NOT NULL DEFAULT 0,
  updated_at          TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (branch_id, item_id),
  FOREIGN KEY (org_id, branch_id) REFERENCES branches (org_id, id) ON DELETE CASCADE,
  FOREIGN KEY (org_id, item_id) REFERENCES inventory_items (org_id, id) ON DELETE CASCADE
);

CREATE TABLE stock_movements (
  id                TEXT PRIMARY KEY,
  org_id            TEXT NOT NULL,
  branch_id         TEXT NOT NULL,
  item_id           TEXT NOT NULL,
  type              TEXT NOT NULL CHECK (type IN ('opening', 'purchase', 'sale', 'sale_reversal', 'waste', 'adjustment', 'count', 'return')),
  qty_delta_milli   BIGINT NOT NULL,
  value_delta_minor BIGINT NOT NULL DEFAULT 0,
  qty_after_milli   BIGINT NOT NULL,
  ref_type          TEXT,
  ref_id            TEXT,
  reason            TEXT,
  created_by        TEXT,
  created_at        TIMESTAMPTZ NOT NULL,
  FOREIGN KEY (org_id, branch_id) REFERENCES branches (org_id, id),
  FOREIGN KEY (org_id, item_id) REFERENCES inventory_items (org_id, id)
);
CREATE INDEX stock_movements_item_idx ON stock_movements (org_id, branch_id, item_id, created_at);
CREATE INDEX stock_movements_ref_idx ON stock_movements (org_id, ref_type, ref_id);
CREATE INDEX stock_movements_created_idx ON stock_movements (org_id, branch_id, created_at);

CREATE TABLE recipe_lines (
  org_id     TEXT NOT NULL,
  product_id TEXT NOT NULL,
  item_id    TEXT NOT NULL,
  qty_milli  BIGINT NOT NULL CHECK (qty_milli > 0),
  PRIMARY KEY (product_id, item_id),
  FOREIGN KEY (org_id, product_id) REFERENCES products (org_id, id) ON DELETE CASCADE,
  FOREIGN KEY (org_id, item_id) REFERENCES inventory_items (org_id, id) ON DELETE CASCADE
);

CREATE TABLE purchase_orders (
  id           TEXT PRIMARY KEY,
  org_id       TEXT NOT NULL,
  branch_id    TEXT NOT NULL,
  supplier_id  TEXT NOT NULL,
  number       TEXT NOT NULL,
  status       TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'ordered', 'partial', 'received', 'cancelled')),
  expected_on  TEXT,
  notes        TEXT NOT NULL DEFAULT '',
  total_minor  BIGINT NOT NULL DEFAULT 0,
  created_by   TEXT,
  created_at   TIMESTAMPTZ NOT NULL,
  ordered_at   TIMESTAMPTZ,
  received_at  TIMESTAMPTZ,
  updated_at   TIMESTAMPTZ NOT NULL,
  UNIQUE (org_id, id),
  UNIQUE (org_id, number),
  FOREIGN KEY (org_id, branch_id) REFERENCES branches (org_id, id),
  FOREIGN KEY (org_id, supplier_id) REFERENCES suppliers (org_id, id)
);

CREATE TABLE purchase_order_lines (
  id                   TEXT PRIMARY KEY,
  org_id               TEXT NOT NULL,
  po_id                TEXT NOT NULL,
  item_id              TEXT NOT NULL,
  qty_milli            BIGINT NOT NULL CHECK (qty_milli > 0),
  line_total_minor     BIGINT NOT NULL CHECK (line_total_minor >= 0),
  received_milli       BIGINT NOT NULL DEFAULT 0,
  received_total_minor BIGINT NOT NULL DEFAULT 0,
  FOREIGN KEY (org_id, po_id) REFERENCES purchase_orders (org_id, id) ON DELETE CASCADE,
  FOREIGN KEY (org_id, item_id) REFERENCES inventory_items (org_id, id)
);
CREATE INDEX po_lines_po_idx ON purchase_order_lines (org_id, po_id);

CREATE TABLE stock_counts (
  id          TEXT PRIMARY KEY,
  org_id      TEXT NOT NULL,
  branch_id   TEXT NOT NULL,
  status      TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'posted', 'cancelled')),
  note        TEXT,
  created_by  TEXT,
  created_at  TIMESTAMPTZ NOT NULL,
  posted_at   TIMESTAMPTZ,
  UNIQUE (org_id, id),
  FOREIGN KEY (org_id, branch_id) REFERENCES branches (org_id, id)
);

CREATE TABLE stock_count_lines (
  org_id             TEXT NOT NULL,
  count_id           TEXT NOT NULL,
  item_id            TEXT NOT NULL,
  expected_milli     BIGINT NOT NULL,
  counted_milli      BIGINT,
  PRIMARY KEY (count_id, item_id),
  FOREIGN KEY (org_id, count_id) REFERENCES stock_counts (org_id, id) ON DELETE CASCADE,
  FOREIGN KEY (org_id, item_id) REFERENCES inventory_items (org_id, id)
);

-- ===========================================================================
-- Customer display & signage
-- ===========================================================================
CREATE TABLE signage_slides (
  id         TEXT PRIMARY KEY,
  org_id     TEXT NOT NULL REFERENCES organizations (id) ON DELETE CASCADE,
  branch_id  TEXT,
  title      TEXT NOT NULL,
  body       TEXT NOT NULL DEFAULT '',
  image_url  TEXT,
  accent     TEXT NOT NULL DEFAULT '#4f46e5',
  duration_s INTEGER NOT NULL DEFAULT 8 CHECK (duration_s BETWEEN 3 AND 120),
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active  BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX signage_org_idx ON signage_slides (org_id, is_active, sort_order);
